```kt
package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.Category
import com.android.tools.lint.detector.api.Context
import com.android.tools.lint.detector.api.Detector
import com.android.tools.lint.detector.api.Detector.GradleScanner
import com.android.tools.lint.detector.api.GradleContext
import com.android.tools.lint.detector.api.Implementation
import com.android.tools.lint.detector.api.Issue
import com.android.tools.lint.detector.api.Location
import com.android.tools.lint.detector.api.Scope
import com.android.tools.lint.detector.api.Severity
import java.util.EnumSet

class AppBundleLocaleChangesDetector : Detector(), GradleScanner {

    private var isApplication = false
    private var hasPlayCore = false
    private var languageSplitDisabled = false

    override fun getApplicableFiles(): EnumSet<Scope> = Scope.GRADLE_SCOPE

    override fun beforeCheckFile(context: Context) {
        isApplication = false
        hasPlayCore = false
        languageSplitDisabled = false
    }

    override fun checkMethodCall(
        context: GradleContext,
        statement: String,
        parent: String?,
        parentParent: String?,
        namedArguments: Map<String, String>,
        unnamedArguments: List<String>,
        cookie: Any
    ) {
        when {
            statement == "apply" && namedArguments["plugin"] == "com.android.application" -> {
                isApplication = true
            }
            statement == "id" && parent == "plugins" && unnamedArguments.any { it == "com.android.application" } -> {
                isApplication = true
            }
            parent == "dependencies" && unnamedArguments.any { PLAY_CORE_REGEX.containsMatchIn(it) } -> {
                hasPlayCore = true
            }
            statement == "enableSplit"
                && parent == "language"
                && parentParent == "bundle"
                && unnamedArguments.any { it == "false" } -> {
                languageSplitDisabled = true
            }
        }
    }

    override fun checkDslPropertyAssignment(
        context: GradleContext,
        property: String,
        value: String,
        parent: String,
        parentParent: String?,
        propertyCookie: Any,
        valueCookie: Any,
        statementCookie: Any
    ) {
        if (property == "enableSplit"
            && value == "false"
            && parent == "language"
            && parentParent == "bundle"
        ) {
            languageSplitDisabled = true
        }
    }

    override fun afterCheckFile(context: Context) {
        if (!isApplication || hasPlayCore || languageSplitDisabled) return

        val contents = context.getContents()?.toString() ?: return
        val token = Regex("""\b(?:bundle|android|plugins)\b""").find(contents)
        val location = if (token != null) {
            Location.create(context.file, contents, token.range.first, token.range.last + 1)
        } else {
            Location.create(context.file)
        }

        val message = "When changing locales at runtime, the App Bundle must not split by " +
            "locale or the Play Core library must be used to download additional locales at " +
            "runtime. Either set bundle.language.enableSplit = false or add a Play Core " +
            "dependency."

        context.report(ISSUE, location, message)
    }

    companion object {
        private val PLAY_CORE_REGEX = Regex(
            """com\.google\.android\.play:(?:core(?:-ktx)?|feature-delivery(?:-ktx)?)"""
        )

        val ISSUE = Issue.create(
            id = "AppBundleLocaleChanges",
            briefDescription = "App Bundle handling of runtime locale changes",
            explanation = """
                When changing locales at runtime (for example, to provide an in-app language
                switcher), the Android App Bundle must be configured to not split by locale or
                the Play Core library must be used to download additional locales at runtime.
                Otherwise users may see missing resources after a locale change.
            """.trimIndent(),
            moreInfo = "https://developer.android.com/guide/app-bundle/configure-base#handling_language_changes",
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(
                AppBundleLocaleChangesDetector::class.java,
                Scope.GRADLE_SCOPE
            )
        )
    }
}
```

